// AK-47 真实模型（来源 J:////武器////ak47////456cfc24057067de62317281692822ef.obj）
// 24,986 顶点 → 32,879 (v,vt) 去重顶点，50,000 三角形
// 坐标系：原始 OBJ 已减去包围盒中心 (cx=-0.001, cy=0.172, cz=-0.011) → 当前坐标中心 (0,0,0)
//   原始: X=枪长(1.18, -X 端为枪口), Y=高度(0.344), Z=宽度(0.09)
//   viewmodel 映射: rotation.y=-PI/2 使 -X(枪口)→-Z(前方), +X(枪托)→+Z(后方)
window.Ak47Model = (function () {
  const POS_B64 = '';
  const UV_B64  = '';
  const IDX_B64 = '';
  const POS_CNT = 32879;
  const UV_CNT  = 32879;
  const IDX_CNT = 150000;
  const IDX_FMT = 'H';

  function b64ToBuf(b64) {
    const bin = atob(b64);
    const arr = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
    return arr.buffer;
  }

  // 构造一个 Object3D（内部含已旋转+平移到 viewmodel 坐标的 Mesh）
  // rotation: 内部已旋转 y=-PI/2（枪口朝 -Z），position 留给调用方微调
  function build(geometry, material) {
    const posBuf = b64ToBuf(POS_B64);
    const uvBuf  = b64ToBuf(UV_B64);
    const idxBuf = b64ToBuf(IDX_B64);

    const posArr = new Float32Array(posBuf);
    const uvArr  = new Float32Array(uvBuf);
    const idxArr = IDX_FMT === 'H' ? new Uint16Array(idxBuf) : new Uint32Array(idxBuf);

    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(posArr, 3));
    geo.setAttribute('uv', new THREE.BufferAttribute(uvArr, 2));
    geo.setIndex(new THREE.BufferAttribute(idxArr, 1));
    // aoMap 必需第二套 UV（uv2）— 复制 uv（与其他武器的 _viewGroup.traverse uv2 补齐逻辑一致）
    geo.setAttribute('uv2', new THREE.BufferAttribute(uvArr.slice(), 2));
    geo.computeVertexNormals();   // OBJ 无 vn，自己计算
    geo.computeBoundingSphere();

    const mesh = new THREE.Mesh(geo, material);
    // 坐标系变换：OBJ +X（枪托）转到 viewmodel +Z，-X（枪口）转到 -Z（枪口朝前方）
    mesh.rotation.y = -Math.PI / 2;
    return mesh;
  }

  return { build, posCount: POS_CNT, idxCount: IDX_CNT, idFormat: IDX_FMT };
})();
